import React, { useEffect, useState } from 'react';
import { Eye, EyeOff } from 'react-feather';
import './App.css';
import LeaveDashboard from './components/LeaveDashboard';

const backendHost = window.location.hostname === 'localhost' ? 'localhost' : window.location.hostname;
const API_ORIGIN = process.env.REACT_APP_API_URL || `http://${backendHost}:5000`;
const AUTH_API_BASE = `${API_ORIGIN}/api/auth`;

const emptyRegistration = {
  employee_name: '',
  job_position_title: '',
  employer: '',
  department: '',
  email: '',
  phone_number: '',
  password: '',
};

const apiError = (payload, fallback) => payload?.error?.message || payload?.error || payload?.message || fallback;

const normalizeUser = (user) => ({
  ...user,
  name: user.full_name || user.name || 'Employee',
  phone: user.phone_number,
});

function App() {
  const [currentUser, setCurrentUser] = useState(null);
  const [authView, setAuthView] = useState('login');
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPhone, setLoginPhone] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [showLoginPassword, setShowLoginPassword] = useState(false);
  const [loginOtp, setLoginOtp] = useState('');
  const [loginChallengeId, setLoginChallengeId] = useState('');
  const [loginOtpSent, setLoginOtpSent] = useState(false);
  const [registration, setRegistration] = useState(emptyRegistration);
  const [registrationOtp, setRegistrationOtp] = useState('');
  const [registrationChallengeId, setRegistrationChallengeId] = useState('');
  const [registrationOtpSent, setRegistrationOtpSent] = useState(false);
  const [resetPassword, setResetPassword] = useState('');
  const [resetOtp, setResetOtp] = useState('');
  const [resetChallengeId, setResetChallengeId] = useState('');
  const [resetOtpSent, setResetOtpSent] = useState(false);
  const [showResetPassword, setShowResetPassword] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState(null);

  const showMessage = (type, text) => setMessage({ type, text });
  const clearMessage = () => setMessage(null);

  const validateEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());

  const validatePhone = (phone) => {
    const cleaned = phone.replace(/[\s\-()+]/g, '');
    return [/^07\d{8}$/, /^01\d{8}$/, /^254[17]\d{8}$/, /^[17]\d{8}$/].some((pattern) => pattern.test(cleaned));
  };

  const saveSession = (data) => {
    localStorage.setItem('okoa_access_token', data.access_token);
    if (data.refresh_token) localStorage.setItem('okoa_refresh_token', data.refresh_token);
    if (data.session_id) localStorage.setItem('okoa_session_id', data.session_id);
    if (data.user?.role) localStorage.setItem('okoa_dashboard_role', data.user.role);
    setCurrentUser(normalizeUser(data.user));
  };

  useEffect(() => {
    const token = localStorage.getItem('okoa_access_token');
    if (!token) return;

    fetch(`${AUTH_API_BASE}/me`, { headers: { Authorization: `Bearer ${token}` } })
      .then(async (response) => {
        const data = await response.json();
        if (!response.ok || !data.user) throw new Error('Session expired');
        setCurrentUser(normalizeUser(data.user));
      })
      .catch(() => {
        localStorage.removeItem('okoa_access_token');
        localStorage.removeItem('okoa_refresh_token');
        localStorage.removeItem('okoa_session_id');
      });
  }, []);

  const submitLogin = async () => {
    clearMessage();
    const identifier = loginEmail.trim();
    if (!identifier || !loginPassword.trim()) {
      showMessage('error', 'Enter your work email and password.');
      return;
    }

    const usingEmail = identifier.includes('@');
    if (usingEmail && !validateEmail(identifier)) {
      showMessage('error', 'Enter a valid work email.');
      return;
    }
    if (!usingEmail && !validatePhone(identifier)) {
      showMessage('error', 'Enter a valid phone number or work email.');
      return;
    }

    setBusy(true);
    try {
      const payload = usingEmail ? { email: identifier.toLowerCase(), password: loginPassword } : { phone_number: identifier, password: loginPassword };
      const response = await fetch(`${AUTH_API_BASE}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await response.json();
      if (!response.ok) {
        if (!usingEmail) {
          const fallback = await fetch(`${AUTH_API_BASE}/phone-login`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ phone_number: identifier, password: loginPassword }),
          });
          const fallbackData = await fallback.json();
          if (!fallback.ok) throw new Error(apiError(fallbackData, 'Unable to sign in.'));
          setLoginChallengeId(fallbackData.challenge_id);
          setLoginOtpSent(true);
          showMessage('success', 'Verification code generated. Check the backend terminal.');
          return;
        }
        throw new Error(apiError(data, 'Unable to sign in.'));
      }
      saveSession(data);
    } catch (error) {
      showMessage('error', error instanceof TypeError ? 'Cannot reach the leave server. Start the backend on port 5000 and try again.' : error.message);
    } finally {
      setBusy(false);
    }
  };

  const verifyLogin = async () => {
    clearMessage();
    if (loginOtp.trim().length !== 6) {
      showMessage('error', 'Enter the 6-digit verification code.');
      return;
    }
    setBusy(true);
    try {
      const response = await fetch(`${AUTH_API_BASE}/verify-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phone_number: loginPhone.trim(), challenge_id: loginChallengeId, otp: loginOtp.trim() }),
      });
      const data = await response.json();
      if (!response.ok || !data.access_token) throw new Error(apiError(data, 'Invalid verification code.'));
      saveSession(data);
    } catch (error) {
      showMessage('error', error.message);
    } finally {
      setBusy(false);
    }
  };

  const submitRegistration = async () => {
    clearMessage();
    const required = ['employee_name', 'job_position_title', 'employer', 'department', 'email', 'phone_number', 'password'];
    if (required.some((field) => !registration[field]?.trim())) {
      showMessage('error', 'Complete your employee name, job title, employer, department, email, phone number, and password.');
      return;
    }
    if (!validatePhone(registration.phone_number.trim())) {
      showMessage('error', 'Enter a valid Kenyan phone number.');
      return;
    }
    if (registration.password.length < 8) {
      showMessage('error', 'Password must be at least 8 characters.');
      return;
    }

    setBusy(true);
    try {
      const response = await fetch(`${AUTH_API_BASE}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...registration, phone_number: registration.phone_number.trim() }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(apiError(data, 'Registration failed.'));
      setRegistrationChallengeId(data.challenge_id);
      setRegistrationOtpSent(true);
      showMessage('success', 'Verification code generated. Check the backend terminal.');
    } catch (error) {
      showMessage('error', error.message);
    } finally {
      setBusy(false);
    }
  };

  const verifyRegistration = async () => {
    clearMessage();
    if (registrationOtp.trim().length !== 6) {
      showMessage('error', 'Enter the 6-digit verification code.');
      return;
    }
    setBusy(true);
    try {
      const response = await fetch(`${AUTH_API_BASE}/verify-registration`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phone_number: registration.phone_number.trim(), challenge_id: registrationChallengeId, otp: registrationOtp.trim() }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(apiError(data, 'Verification failed.'));
      setRegistrationOtpSent(false);
      setRegistrationOtp('');
      setAuthView('login');
      setLoginPhone(registration.phone_number);
      setLoginPassword('');
      showMessage('success', data.message || 'Registration verified. Your account is pending approval.');
    } catch (error) {
      showMessage('error', error.message);
    } finally {
      setBusy(false);
    }
  };

  const requestPasswordReset = async () => {
    clearMessage();
    const identifier = loginEmail.trim();
    const hasEmail = identifier.includes('@');
    if (!identifier) {
      showMessage('error', 'Enter your work email to reset your password.');
      return;
    }
    if (hasEmail && !validateEmail(identifier)) {
      showMessage('error', 'Enter a valid work email.');
      return;
    }
    if (!hasEmail && !validatePhone(loginPhone.trim())) {
      showMessage('error', 'Enter a valid Kenyan phone number.');
      return;
    }
    setBusy(true);
    try {
      const payload = hasEmail ? { email: identifier.toLowerCase() } : { phone_number: loginPhone.trim() };
      const response = await fetch(`${AUTH_API_BASE}/request-password-reset`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await response.json();
      if (!response.ok || !data.challenge_id) throw new Error(apiError(data, 'Unable to request a reset code.'));
      setResetChallengeId(data.challenge_id);
      setResetOtpSent(true);
      showMessage('success', 'Reset code generated. Check the backend terminal.');
    } catch (error) {
      showMessage('error', error.message);
    } finally {
      setBusy(false);
    }
  };

  const resetPasswordRequest = async () => {
    clearMessage();
    if (resetOtp.trim().length !== 6 || resetPassword.length < 8) {
      showMessage('error', 'Enter the 6-digit code and a password of at least 8 characters.');
      return;
    }
    setBusy(true);
    try {
      const payload = loginEmail.trim().includes('@')
        ? { email: loginEmail.trim().toLowerCase(), challenge_id: resetChallengeId, otp: resetOtp.trim(), new_password: resetPassword }
        : { phone_number: loginPhone.trim(), challenge_id: resetChallengeId, otp: resetOtp.trim(), new_password: resetPassword };
      const response = await fetch(`${AUTH_API_BASE}/reset-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(apiError(data, 'Unable to reset password.'));
      setResetOtpSent(false);
      setAuthView('login');
      setLoginPassword('');
      showMessage('success', 'Password reset successfully. You can now sign in.');
    } catch (error) {
      showMessage('error', error.message);
    } finally {
      setBusy(false);
    }
  };

  const handleLogout = async () => {
    const refreshToken = localStorage.getItem('okoa_refresh_token');
    try {
      if (refreshToken) {
        await fetch(`${AUTH_API_BASE}/logout`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${refreshToken}` },
        });
      }
    } finally {
      localStorage.removeItem('okoa_access_token');
      localStorage.removeItem('okoa_refresh_token');
      localStorage.removeItem('okoa_session_id');
      setCurrentUser(null);
      setLoginOtpSent(false);
      setLoginOtp('');
      setAuthView('login');
      showMessage('success', 'You have been signed out.');
    }
  };

  if (currentUser) {
    const roleLabel = {
      employee: 'Employee Dashboard',
      manager: 'Manager Dashboard',
      hr_admin: 'Human Resources Dashboard',
    }[currentUser.role] || 'Dashboard';

    return (
      <>
        <div className="role-banner" style={{ padding: '0.75rem 1rem', background: '#edfdf8', borderBottom: '1px solid #d8f3eb', color: '#0f172a', fontWeight: 600 }}>
          {roleLabel}
        </div>
        <LeaveDashboard currentUser={currentUser} onUserUpdated={(user) => setCurrentUser(normalizeUser(user))} handleLogout={handleLogout} />
      </>
    );
  }

  const isRegistration = authView === 'register';
  const isReset = authView === 'reset';
  const isOtp = isRegistration ? registrationOtpSent : isReset ? resetOtpSent : loginOtpSent;

  return (
    <div className="activation-container auth-page">
      <div className={`auth-card ${isRegistration ? 'registration-auth-card' : 'login-card'}`}>
        <aside className="auth-visual-panel">
          <p className="auth-visual-kicker">LEAVE, MADE SIMPLE</p>
          <h2>More time for the work that matters.</h2>
          <p>Request leave, track balances, and stay aligned with your team from one calm workspace.</p>
          <div className="auth-visual-rule" />
          <span>Secure employee access</span>
        </aside>
        <section className="auth-form-panel">
          <div className="auth-panel-logo"><img className="auth-logo" src="/okoa_float_logo.svg" alt="Okoa Float" /></div>
          <div className="auth-form-heading">
            <span className="auth-eyebrow">EMPLOYEE PORTAL</span>
            <h1>{isRegistration ? 'Create your account' : isReset ? 'Reset your password' : isOtp ? 'Verify your identity' : 'Welcome back'}</h1>
            <p>{isRegistration ? 'Register to manage your leave.' : isReset ? 'Use the code generated for your work email or mobile number.' : 'Sign in to manage your leave.'}</p>
          </div>

          {message && <div className={`login-${message.type === 'error' ? 'error' : 'success'}`} role="alert">{message.text}</div>}

          {isRegistration ? (
            registrationOtpSent ? (
              <OtpForm value={registrationOtp} onChange={setRegistrationOtp} onSubmit={verifyRegistration} busy={busy} label="Enter registration code" />
            ) : <RegistrationForm values={registration} setValues={setRegistration} onSubmit={submitRegistration} busy={busy} />
          ) : isReset ? (
            resetOtpSent ? (
              <>
                <OtpForm value={resetOtp} onChange={setResetOtp} onSubmit={resetPasswordRequest} busy={busy} label="Enter reset code" />
                <PasswordField value={resetPassword} onChange={setResetPassword} visible={showResetPassword} setVisible={setShowResetPassword} label="New password" />
              </>
            ) : (
              <>
                <div className="activation-input-group"><label>Work email</label><input type="email" value={loginEmail} onChange={(event) => setLoginEmail(event.target.value)} placeholder="name@company.com" className="activation-input" disabled={busy} onKeyDown={(event) => event.key === 'Enter' && requestPasswordReset()} /></div>
                <div className="activation-input-group"><label>Phone number (optional fallback)</label><input type="tel" value={loginPhone} onChange={(event) => setLoginPhone(event.target.value)} placeholder="0712 345 678" className="activation-input" disabled={busy} onKeyDown={(event) => event.key === 'Enter' && requestPasswordReset()} /></div>
                <div className="activation-actions"><button onClick={requestPasswordReset} disabled={busy} className="btn-activate">{busy ? 'Please wait...' : 'Send reset code'}</button></div>
              </>
            )
          ) : loginOtpSent ? (
            <OtpForm value={loginOtp} onChange={setLoginOtp} onSubmit={verifyLogin} busy={busy} label="Enter 6-digit login code" />
          ) : (
            <>
              <div className="activation-input-group"><label>Work email</label><input type="email" autoComplete="email" value={loginEmail} onChange={(event) => setLoginEmail(event.target.value)} placeholder="name@company.com" className="activation-input" disabled={busy} onKeyDown={(event) => event.key === 'Enter' && submitLogin()} /></div>
              <PasswordField value={loginPassword} onChange={setLoginPassword} visible={showLoginPassword} setVisible={setShowLoginPassword} label="Password" />
              <div className="activation-actions"><button onClick={submitLogin} disabled={busy} className="btn-activate">{busy ? 'Authenticating...' : 'Sign in'}</button></div>
              <div className="auth-links"><button onClick={() => { clearMessage(); setAuthView('reset'); }} className="btn-resend-link">Forgot password?</button><button onClick={() => { clearMessage(); setAuthView('register'); }} className="btn-resend-link">Register here</button></div>
            </>
          )}

          {(isOtp || isRegistration || isReset) && <div className="auth-links"><button className="btn-resend-link" onClick={() => { clearMessage(); setAuthView('login'); setLoginOtpSent(false); setRegistrationOtpSent(false); setResetOtpSent(false); }}>Back to sign in</button></div>}
        </section>
      </div>
    </div>
  );
}

const PhoneForm = ({ value, onChange, onSubmit, busy, label, buttonLabel }) => (
  <div className="activation-input-group login-phone-group">
    <label>{label}</label>
    <input type="tel" autoComplete="tel" value={value} onChange={(event) => onChange(event.target.value)} placeholder="0712 345 678" className="activation-input" disabled={busy} onKeyDown={(event) => event.key === 'Enter' && onSubmit?.()} />
    {onSubmit && <div className="activation-actions"><button onClick={onSubmit} disabled={busy} className="btn-activate">{busy ? 'Please wait...' : buttonLabel}</button></div>}
  </div>
);

const PasswordField = ({ value, onChange, visible, setVisible, label }) => (
  <div className="activation-input-group">
    <label>{label}</label>
    <div className="password-input-wrapper">
      <input type={visible ? 'text' : 'password'} autoComplete="new-password" value={value} onChange={(event) => onChange(event.target.value)} placeholder="Enter your password" className="activation-input" />
      <button type="button" className="password-toggle-btn text-toggle" aria-label={visible ? 'Hide password' : 'Show password'} onClick={() => setVisible(!visible)}>{visible ? <EyeOff size={18} /> : <Eye size={18} />}</button>
    </div>
  </div>
);

const OtpForm = ({ value, onChange, onSubmit, busy, label }) => (
  <>
    <div className="activation-input-group"><label>{label}</label><input type="text" inputMode="numeric" maxLength={6} value={value} onChange={(event) => onChange(event.target.value.replace(/\D/g, ''))} placeholder="_ _ _ _ _ _" className="activation-input otp-input" autoFocus /></div>
    <div className="activation-actions"><button onClick={onSubmit} disabled={busy} className="btn-activate">{busy ? 'Verifying...' : 'Verify code'}</button></div>
  </>
);

const RegistrationForm = ({ values, setValues, onSubmit, busy }) => {
  const [showPassword, setShowPassword] = useState(false);

  return <>
    <div className="registration-form-grid">
      {[
      ['employee_name', 'Employee name', 'text'],
      ['job_position_title', 'Job position title', 'text'],
      ['employer', 'Employer', 'text'],
      ['department', 'Department', 'text'],
      ['email', 'Work email', 'email'],
      ['phone_number', 'Phone number', 'tel'],
      ].map(([field, label, type]) => <div className="activation-input-group" key={field}><label>{label}</label><input type={type} value={values[field]} onChange={(event) => setValues({ ...values, [field]: event.target.value })} placeholder={label} className="activation-input" /></div>)}
      <PasswordField value={values.password} onChange={(password) => setValues({ ...values, password })} visible={showPassword} setVisible={setShowPassword} label="Password" />
    </div>
    <div className="activation-actions"><button onClick={onSubmit} disabled={busy} className="btn-activate">{busy ? 'Registering...' : 'Register'}</button></div>
  </>
};

export default App;
